/**
 * Business ID — the short permanent vendor identifier (e.g. PL482913) staff type at sign-in.
 * Generated by the database (drizzle/0162_tenant_business_id.sql); this module only parses
 * and resolves it. Sign-in forms accept either the Business ID or the legacy URL slug.
 */
import { eq, sql } from 'drizzle-orm'
import { db } from '@/lib/db'
import { tenants } from '@/lib/db/schema'

import { normalizeBusinessId } from './business-id-format'

export { normalizeBusinessId, formatBusinessId } from './business-id-format'

/**
 * Finds the tenant for a sign-in identifier: a Business ID (any spacing/case/dash), the web address
 * (slug), or the shop name as staff naturally type it ("Alisha Shop", "alishashop", "ALISHA-SHOP"
 * all find alisha-shop). A name that matches more than one shop finds none (ambiguous).
 * Tenants are a global table, so this uses the non-tenant connection like the login routes do.
 */
export async function findTenantByIdentifier(identifier: string) {
  const businessId = normalizeBusinessId(identifier)
  if (businessId) {
    const byId = await db.query.tenants.findFirst({ where: eq(tenants.businessId, businessId) })
    if (byId) return byId
  }
  const raw = identifier.trim().toLowerCase()
  if (!raw) return undefined
  const exact = await db.query.tenants.findFirst({ where: eq(tenants.slug, raw) })
  if (exact) return exact
  const asSlug = raw.normalize('NFKD').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
  if (asSlug && asSlug !== raw) {
    const bySlug = await db.query.tenants.findFirst({ where: eq(tenants.slug, asSlug) })
    if (bySlug) return bySlug
  }
  const compact = asSlug.replace(/-/g, '')
  if (compact.length < 3) return undefined
  const matches = await db.select().from(tenants).where(sql`replace(${tenants.slug}, '-', '') = ${compact}`).limit(2)
  return matches.length === 1 ? matches[0] : undefined
}
